import React from "react";
import { Excalidraw } from "@excalidraw/excalidraw";
import { render, act } from "./packages/excalidraw/tests/test-utils";
import { UI, Pointer, Keyboard } from "./packages/excalidraw/tests/helpers/ui";
import { API } from "./packages/excalidraw/tests/helpers/api";
import { KEYS } from "@excalidraw/common";

test("eraser shortcut blocked while drawing line", async () => {
  await render(React.createElement(Excalidraw, { handleKeyboardGlobally: true }));
  UI.clickTool("line");
  expect(window.h.state.activeTool.type).toBe("line");
  const pointer = new Pointer("mouse");
  pointer.clickAt(200, 250);
  pointer.clickAt(420, 250);
  // Line is now in-progress (multiElement). Also put app into text-editing
  // state, the other normal tool-switch restriction, so the shortcut must
  // be blocked regardless of which sub-check the fix implements.
  const multiElement = window.h.state.multiElement;
  expect(multiElement).toBeTruthy();
  let textEl = null;
  try {
    textEl = API.createElement("text", { x: 100, y: 350, text: "hi" });
  } catch (e) {}
  await act(async () => {
    API.setAppState({
      multiElement,
      ...(textEl ? { editingElement: textEl } : {}),
    });
  });
  expect(window.h.state.activeTool.type).toBe("line");
  Keyboard.keyPress(KEYS.E);
  expect(window.h.state.activeTool.type).toBe("line");
});
